artifacts.solve_py:
import csv, json, os, sys
from pyscipopt import Model, quicksum

BASE = "/app"
DATA = os.path.join(BASE, "data")
SUB = os.path.join(BASE, "submissions")
os.makedirs(SUB, exist_ok=True)

def read_csv(name):
    with open(os.path.join(DATA, name)) as f:
        return list(csv.DictReader(f))

cfg = json.load(open(os.path.join(DATA, "config.json")))
DAYS = list(range(1, cfg["planning_days"] + 1))
COVISIT = cfg["co_visit_setup_saving_hours"]

vessels = {r["vessel_id"]: r for r in read_csv("vessels.csv")}
turbines = {r["turbine_id"]: r for r in read_csv("turbines.csv")}
patterns = read_csv("route_patterns.csv")
works = read_csv("work_orders.csv")
techpool = read_csv("technician_pool.csv")
spares = read_csv("spare_inventory.csv")
sail_lim = {r["vessel_id"]: int(r["max_sailing_days"]) for r in read_csv("vessel_sailing_limits.csv")}
turnaround = read_csv("route_turnaround_rules.csv")
strlim = {r["string_id"]: r for r in read_csv("string_daily_limits.csv")}
strrules = read_csv("string_opportunity_rules.csv")

for p in patterns:
    p["day"] = int(p["day"])
    p["turbines"] = [t for t in p["covered_turbines"].split(";") if t]
    p["work_hour_capacity"] = float(p["work_hour_capacity"])
    p["route_cost"] = float(p["route_cost"])
    p["access_score"] = int(p["access_score"])
    p["fatigue_units"] = float(p["fatigue_units"])

for w in works:
    for k in ["earliest_day", "due_day", "latest_day"]:
        w[k] = int(w[k])
    w["mandatory"] = w["mandatory"] == "yes"
    w["duration_hours"] = float(w["duration_hours"])
    w["technicians_required"] = int(w["technicians_required"])
    w["spare_units"] = int(w["spare_units"])
    w["min_access_score"] = int(w["min_access_score"])
    w["lateness_penalty_per_day"] = float(w["lateness_penalty_per_day"])
    w["downtime_cost_per_day"] = float(w["downtime_cost_per_day"])
    w["deferral_penalty"] = float(w["deferral_penalty"])
    w["opportunity_credit"] = float(w["opportunity_credit"])
    w["string"] = turbines[w["turbine_id"]]["string_id"]

tech = {}
for r in techpool:
    tech[(int(r["day"]), r["skill"])] = (float(r["regular_hours"]), float(r["overtime_hours"]), float(r["overtime_cost_per_hour"]))

spav = {}
for r in spares:
    spav[(int(r["day"]), r["spare_type"])] = int(r["available_units"])

# feasible assignment combos
def cap_ok(pcap, req):
    return (pcap == "cable") or (req == "standard")

combos = []  # (w, d, v, p)
for w in works:
    for d in range(w["earliest_day"], w["latest_day"] + 1):
        for p in patterns:
            if p["day"] != d:
                continue
            if w["turbine_id"] not in p["turbines"]:
                continue
            if not cap_ok(p["capability"], w["required_capability"]):
                continue
            if p["access_score"] < w["min_access_score"]:
                continue
            combos.append((w, d, p["vessel_id"], p))

m = Model("offshore_wind_maintenance")
m.setMinimize()
gap = 0.0005
m.setRealParam("limits/gap", gap)
tl = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
m.setRealParam("limits/time", float(tl) if tl else 300.0)

x = {}
for p in patterns:
    x[p["pattern_id"]] = m.addVar(vtype="B", obj=0.0, name=f"x_{p['pattern_id']}")

y = {}
for (w, d, v, p) in combos:
    y[(w["task_id"], d, v, p["pattern_id"])] = m.addVar(vtype="B", obj=0.0, name=f"y_{w['task_id']}_{d}_{v}_{p['pattern_id']}")

# z_w,d
z = {}
for w in works:
    for d in range(w["earliest_day"], w["latest_day"] + 1):
        z[(w["task_id"], d)] = m.addVar(vtype="B", obj=0.0, name=f"z_{w['task_id']}_{d}")

# link z
for w in works:
    for d in range(w["earliest_day"], w["latest_day"] + 1):
        m.addCons(z[(w["task_id"], d)] == quicksum(y[(w["task_id"], d, v, pid)] for (ww, dd, v, pp) in combos if ww["task_id"] == w["task_id"] and dd == d for pid in [pp["pattern_id"]]), name=f"zlink_{w['task_id']}_{d}")

# mandatory exactly once, preventive at most once
for w in works:
    total = quicksum(z[(w["task_id"], d)] for d in range(w["earliest_day"], w["latest_day"] + 1))
    if w["mandatory"]:
        m.addCons(total == 1, name=f"mand_{w['task_id']}")
    else:
        m.addCons(total <= 1, name=f"prev_{w['task_id']}")

# y <= x
for (w, d, v, p) in combos:
    m.addCons(y[(w["task_id"], d, v, p["pattern_id"])] <= x[p["pattern_id"]], name=f"yx_{w['task_id']}_{p['pattern_id']}")

# one route per vessel-day
for v in vessels:
    for d in DAYS:
        plist = [p["pattern_id"] for p in patterns if p["vessel_id"] == v and p["day"] == d]
        if plist:
            m.addCons(quicksum(x[pid] for pid in plist) <= 1, name=f"oneday_{v}_{d}")

# sailing limits
for v in vessels:
    plist = [p["pattern_id"] for p in patterns if p["vessel_id"] == v]
    m.addCons(quicksum(x[pid] for pid in plist) <= sail_lim[v], name=f"sail_{v}")

# turnaround forbidden pairs
for r in turnaround:
    a, b = r["previous_pattern_id"], r["next_pattern_id"]
    if a in x and b in x:
        m.addCons(x[a] + x[b] <= 1, name=f"turn_{a}_{b}")

# two-day fatigue
for v in vessels:
    lim = float(vessels[v]["two_day_fatigue_limit"])
    for d in DAYS[:-1]:
        plist = [p["pattern_id"] for p in patterns if p["vessel_id"] == v and p["day"] in (d, d + 1)]
        m.addCons(quicksum(float(patterns[[q["pattern_id"] for q in patterns].index(pid)]["fatigue_units"]) * x[pid] for pid in plist) <= lim, name=f"fat_{v}_{d}")

# work hour capacity with co-visit saving
# group combos by (v,d,p)
from collections import defaultdict
by_vdp = defaultdict(list)
for (w, d, v, p) in combos:
    by_vdp[(v, d, p["pattern_id"])].append(w)

s = {}
u = {}
for (v, d, pid), wlist in by_vdp.items():
    p = [pp for pp in patterns if pp["pattern_id"] == pid][0]
    turbset = set(p["turbines"])
    for t in turbset:
        tw = [w for w in wlist if w["turbine_id"] == t]
        if not tw:
            continue
        s[(t, v, d, pid)] = m.addVar(vtype="C", lb=0.0, ub=float(len(tw)), obj=0.0, name=f"s_{t}_{v}_{d}_{pid}")
        u[(t, v, d, pid)] = m.addVar(vtype="B", obj=0.0, name=f"u_{t}_{v}_{d}_{pid}")
        n = quicksum(y[(w["task_id"], d, v, pid)] for w in tw)
        m.addCons(u[(t, v, d, pid)] >= n - (len(tw) - 1), name=f"uge_{t}_{v}_{d}_{pid}")
        m.addCons(s[(t, v, d, pid)] <= n - 1 + (1 - u[(t, v, d, pid)]), name=f"sle_{t}_{v}_{d}_{pid}")
        m.addCons(s[(t, v, d, pid)] <= n, name=f"sle2_{t}_{v}_{d}_{pid}")
        m.addCons(s[(t, v, d, pid)] >= 0, name=f"sge0_{t}_{v}_{d}_{pid}")
    total_hours = quicksum(w["duration_hours"] * y[(w["task_id"], d, v, pid)] for w in wlist)
    saving = COVISIT * quicksum(s[(t, v, d, pid)] for t in turbset if (t, v, d, pid) in s)
    m.addCons(total_hours - saving <= p["work_hour_capacity"], name=f"hours_{v}_{d}_{pid}")

# technician berths
for (v, d, pid), wlist in by_vdp.items():
    m.addCons(quicksum(w["technicians_required"] * y[(w["task_id"], d, v, pid)] for w in wlist) <= int(vessels[v]["technician_berths"]), name=f"berth_{v}_{d}_{pid}")

# deck spares
for (v, d, pid), wlist in by_vdp.items():
    m.addCons(quicksum(w["spare_units"] * y[(w["task_id"], d, v, pid)] for w in wlist) <= int(vessels[v]["deck_spare_units"]), name=f"deck_{v}_{d}_{pid}")

# overtime vars
ot = {}
for d in DAYS:
    for k in ["blade", "electrical", "mechanical", "cable"]:
        _, otmax, _ = tech[(d, k)]
        ot[(d, k)] = m.addVar(vtype="C", lb=0.0, ub=otmax, obj=0.0, name=f"ot_{d}_{k}")

# technician pool
for d in DAYS:
    for k in ["blade", "electrical", "mechanical", "cable"]:
        reg, otmax, otc = tech[(d, k)]
        demand = quicksum(w["technicians_required"] * w["duration_hours"] * y[(w["task_id"], d, v, pid)] for (w, dd, v, p) in combos if dd == d and w["skill"] == k for pid in [p["pattern_id"]])
        m.addCons(demand <= reg + ot[(d, k)], name=f"tech_{d}_{k}")

# spare inventory
for d in DAYS:
    for st, av in [(k, v) for (dd, k), v in spav.items() if dd == d]:
        if st == "none":
            continue
        demand = quicksum(w["spare_units"] * y[(w["task_id"], d, v, pid)] for (w, dd, v, p) in combos if dd == d and w["spare_type"] == st for pid in [p["pattern_id"]])
        m.addCons(demand <= av, name=f"spare_{d}_{st}")

# string daily limits
for g, r in strlim.items():
    maxm = int(r["max_mandatory_tasks_per_day"])
    maxt = int(r["max_total_tasks_per_day"])
    for d in DAYS:
        mand = quicksum(y[(w["task_id"], d, v, pid)] for (w, dd, v, p) in combos if dd == d and w["string"] == g and w["mandatory"] for pid in [p["pattern_id"]])
        total = quicksum(y[(w["task_id"], d, v, pid)] for (w, dd, v, p) in combos if dd == d and w["string"] == g for pid in [p["pattern_id"]])
        m.addCons(mand <= maxm, name=f"strm_{g}_{d}")
        m.addCons(total <= maxt, name=f"strt_{g}_{d}")

# objective components
obj = []
# route costs
for p in patterns:
    obj.append(p["route_cost"] * x[p["pattern_id"]])

# lateness + downtime for mandatory
for w in works:
    if not w["mandatory"]:
        continue
    for d in range(w["earliest_day"], w["latest_day"] + 1):
        late = w["lateness_penalty_per_day"] * max(0, d - w["due_day"])
        down = w["downtime_cost_per_day"] * (d - w["earliest_day"])
        obj.append((late + down) * z[(w["task_id"], d)])

# deferral for preventive omitted
for w in works:
    if not w["mandatory"]:
        total = quicksum(z[(w["task_id"], d)] for d in range(w["earliest_day"], w["latest_day"] + 1))
        obj.append(w["deferral_penalty"] * (1 - total))

# overtime cost
for d in DAYS:
    for k in ["blade", "electrical", "mechanical", "cable"]:
        _, _, otc = tech[(d, k)]
        obj.append(otc * ot[(d, k)])

# same-turbine anchor credit for preventive
a_credit = {}
for w in works:
    if w["mandatory"] or w["opportunity_credit"] <= 0:
        continue
    for d in range(w["earliest_day"], w["latest_day"] + 1):
        for v in vessels:
            a_credit[(w["task_id"], d, v)] = m.addVar(vtype="B", obj=0.0, name=f"ac_{w['task_id']}_{d}_{v}")
            # <= assignment of w on (d,v)
            m.addCons(a_credit[(w["task_id"], d, v)] <= quicksum(y[(w["task_id"], d, v, pid)] for (ww, dd, vv, p) in combos if ww["task_id"] == w["task_id"] and dd == d and vv == v for pid in [p["pattern_id"]]), name=f"ac1_{w['task_id']}_{d}_{v}")
            # <= mandatory presence same turbine/day/vessel
            mandsum = quicksum(y[(ww["task_id"], d, v, pid)] for (ww, dd, vv, p) in combos if dd == d and vv == v and ww["mandatory"] and ww["turbine_id"] == w["turbine_id"] for pid in [p["pattern_id"]])
            m.addCons(a_credit[(w["task_id"], d, v)] <= mandsum, name=f"ac2_{w['task_id']}_{d}_{v}")
            obj.append(-w["opportunity_credit"] * a_credit[(w["task_id"], d, v)])

# string opportunity rules
for r in strrules:
    anchor = r["anchor_task_id"]
    g = r["string_id"]
    elig = set(t for t in r["eligible_task_types"].split(";") if t)
    credit = float(r["credit_per_task"])
    maxc = int(r["max_credit_tasks"])
    aw = [w for w in works if w["task_id"] == anchor][0]
    # anchor day var
    anchor_day = {}
    for d in range(aw["earliest_day"], aw["latest_day"] + 1):
        anchor_day[d] = z[(anchor, d)]
    q = {}
    for w in works:
        if w["task_id"] == anchor or w["string"] != g or w["task_type"] not in elig:
            continue
        for d in range(max(w["earliest_day"], aw["earliest_day"]), min(w["latest_day"], aw["latest_day"]) + 1):
            if d not in anchor_day:
                continue
            q[(r["rule_id"], w["task_id"], d)] = m.addVar(vtype="B", obj=0.0, name=f"q_{r['rule_id']}_{w['task_id']}_{d}")
            m.addCons(q[(r["rule_id"], w["task_id"], d)] <= z[(w["task_id"], d)], name=f"q1_{r['rule_id']}_{w['task_id']}_{d}")
            m.addCons(q[(r["rule_id"], w["task_id"], d)] <= anchor_day[d], name=f"q2_{r['rule_id']}_{w['task_id']}_{d}")
            obj.append(-credit * q[(r["rule_id"], w["task_id"], d)])
    if q:
        m.addCons(quicksum(qv for qv in q.values()) <= maxc, name=f"qmax_{r['rule_id']}")

m.setObjective(quicksum(obj), "sense", "minimize")
m.hideOutput()
m.optimize()

status = m.getStatus()
print("STATUS:", status)
best = m.getBestSol()
objval = m.getObjVal()
print("OBJ:", objval)

# extract solution
sel_routes = []
for p in patterns:
    if best[x[p["pattern_id"]]] > 0.5:
        sel_routes.append((p["day"], p["vessel_id"], p["pattern_id"]))

work_rows = []
for (w, d, v, p) in combos:
    if best[y[(w["task_id"], d, v, p["pattern_id"]]]] > 0.5:
        work_rows.append((d, v, p["pattern_id"], w["task_id"]))

with open(os.path.join(SUB, "solution.csv"), "w", newline="") as f:
    wr = csv.writer(f)
    wr.writerow(["record_type", "day", "vessel_id", "pattern_id", "task_id"])
    for (d, v, pid) in sorted(sel_routes):
        wr.writerow(["route", d, v, pid, ""])
    for (d, v, pid, tid) in sorted(work_rows):
        wr.writerow(["work", d, v, pid, tid])

# validation
done = {}
for (d, v, pid, tid) in work_rows:
    done.setdefault(tid, []).append(d)
for w in works:
    if w["mandatory"]:
        assert tid in done and len(done[w["task_id"]]) == 1, f"mandatory {w['task_id']} not exactly once"
        dd = done[w["task_id"]][0]
        assert w["earliest_day"] <= dd <= w["latest_day"], f"window {w['task_id']}"
print("VALIDATION OK")
print("routes:", len(sel_routes), "work:", len(work_rows))
